var ITEMS=[["Kill subvocalization","Stop sounding every word; see phrases, not syllables."], ["Widen the eye span","Take in 3-4 words per fixation instead of one."], ["Reduce fixations","Fewer stops per line; train with a pacer."], ["Use a pacer","Finger or pen moving slightly faster than comfort."], ["Eliminate regression","No re-reading; trust forward motion."], ["Preview first","Skim headings, intro, and conclusion before deep reading."], ["Set a purpose","Know what you need before starting."], ["Question-driven reading","Read to answer specific questions."], ["Chunk difficult text","Slow for dense passages, fast for easy."], ["Timed sessions","15-minute sprints with a words-per-minute count."], ["Track WPM weekly","Words per minute plus a 5-question quiz."], ["Stop at chapter ends","Recall the chapter before continuing."], ["Read daily","30+ minutes every day without exception."], ["Vary material","Fiction, nonfiction, technical \u2014 all train differently."], ["No multitasking","Single focus; music without lyrics only."], ["Good lighting","Bright, even light reduces fatigue."], ["Posture matters","Upright, book at angle, distance steady."], ["Take notes sparingly","Margin marks, not transcription."], ["Summarize aloud","One-minute verbal summary per section."], ["Teach what you read","Explain to someone within 24 hours."], ["Re-read strategically","Second pass only on flagged sections."], ["Skim to filter","Skip what you already know or don't need."], ["Vertical reading drills","Practice reading down columns of words."], ["Comprehension first","Never trade understanding for speed."], ["Monthly speed test","Same text monthly; chart WPM and quiz scores."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
